using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class SignalSignClearance{
[InitializeOnLoadMethod]static void Init(){EditorApplication.delayCall+=Run;}
static void Run(){if(!File.Exists("SignalSignClearance.request"))return;File.Delete("SignalSignClearance.request");try{
var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Signal.prefab");var mesh=prefab.GetComponent<MeshFilter>().sharedMesh;string path=AssetDatabase.GetAssetPath(mesh);if(!File.Exists("SignalBackup/BeforeSignClearance.asset"))File.Copy(path,"SignalBackup/BeforeSignClearance.asset");var q=prefab.transform.localRotation;var inverse=Quaternion.Inverse(q);var v=mesh.vertices;var parts=SignalAudit.Parts(mesh);var yellow=parts.Where(p=>{var b=Bounds(p,v,q);return Mathf.Abs(b.center.y-3.707f)<.03f&&Mathf.Abs(b.center.z+.03f)<.05f&&b.size.y>.7f;}).SelectMany(p=>p).ToArray();var white=parts.Where(p=>{var b=Bounds(p,v,q);return Mathf.Abs(b.center.y-4.669f)<.04f&&Mathf.Abs(b.center.z+2.476f)<.05f&&b.size.y>.5f;}).SelectMany(p=>p).ToArray();if(yellow.Length==0||white.Length==0)throw new Exception("Sign geometry not identified");
float dy=.20f-yellow.Min(i=>(q*v[i]).x),dw=.09f-white.Min(i=>(q*v[i]).x);foreach(int i in yellow)v[i]+=inverse*new Vector3(dy,0,0);foreach(int i in white)v[i]+=inverse*new Vector3(dw,0,0);mesh.vertices=v;mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);AssetDatabase.SaveAssets();SceneView.RepaintAll();File.WriteAllText("VenueLightingReview/SignClearance.txt","SUCCESS: yellow sign moved "+dy+"m and white sign "+dw+"m forwards, including backing layers. Shared prefab mesh updated; textures, triangle count and controls preserved.");
var r=UnityEngine.Object.FindObjectsOfType<CityTrafficSignal>().FirstOrDefault();var c=UnityEngine.Object.FindObjectOfType<CityDayNightController>(true);if(r&&c){var target=r.transform.TransformPoint(inverse*new Vector3(0,3.95f,-1.2f));var front=r.transform.rotation*inverse*Vector3.right;var pos=target+front*5+Vector3.up*.25f;CityLightingBuilder.Capture(c,Tuple.Create(pos,Quaternion.LookRotation(target-pos)),"Signal-Signs-Fixed");}
}catch(Exception e){File.WriteAllText("VenueLightingReview/SignClearance.txt","FAILED "+e);Debug.LogException(e);}}
static Bounds Bounds(int[] part,Vector3[] v,Quaternion q){var b=new Bounds(q*v[part[0]],Vector3.zero);foreach(int i in part)b.Encapsulate(q*v[i]);return b;}
}
